def pmok(x,y):
    PA,MA=x; PB,MB=y
    return ((MA==0 or (MA&PB)!=0) and (MB==0 or (MB&PA)!=0))

def feasible_core(core, es, edges, core_port_map, raw=False, tr=None):
    sm=ext_slot_map(edges); em={1:es[0],2:es[1],3:es[2]}
    for u,v in edges:
        if u==0:
            p=core_port_map[v]
            if raw:
                if not pmok(rawslot(tr,p),em[v][1][sm[v][0]]): return False
            else:
                if not bridge_ok(core,p,em[v],sm[v][0]): return False
    return True

def core_compatible(core,i,j,env):
    # synthetic event exposes the two correlated interface P/Ms; bridge_ok remains local,
    # but env membership already enforces E1-E2 correlation.
    s1=(0,(env[1][0],),0,0,0); s2=(0,(env[1][1],),0,0,0)
    return bridge_ok(core,i,s1,0) and bridge_ok(core,j,s2,0)

def pm_bridge(pmA, pmB):
    PA,MA=pmA; PB,MB=pmB
    return ((MA==0 or (MA&PB)!=0) and (MB==0 or (MB&PA)!=0))

def feasible_at(relation, envrel, i,j, threshold):
    # Exact signature-indexed feasibility. The environment remains JOINT:
    # each item is a correlated pair (iface1,iface2) that survived E1-E2 internally.
    cps={(c[1][i],c[1][j]) for c in relation if int(c[2])>=threshold}
    eps={e[1] for e in envrel if int(e[3])>=threshold}
    for cp1,cp2 in cps:
        for ep1,ep2 in eps:
            if pm_bridge(cp1,ep1) and pm_bridge(cp2,ep2):
                return True
    return False

